struct DirectParser<'i> {
    input: &'i str,
    bytes: &'i [u8],
    cursor: usize,
}

impl<'i> DirectParser<'i> {
    #[inline(always)]
    fn new(input: &'i str) -> Self {
        Self {
            input,
            bytes: input.as_bytes(),
            cursor: 0,
        }
    }

    #[inline(always)]
    fn ws(&mut self) {
        self.cursor = skip_ascii_whitespace(self.bytes, self.cursor);
    }

    #[inline(always)]
    fn take(&mut self, byte: u8) -> bool {
        if self.bytes.get(self.cursor) == Some(&byte) {
            self.cursor += 1;
            true
        } else {
            false
        }
    }

    #[inline(always)]
    fn expect(&mut self, byte: u8) -> Result<(), DirectBuildError<'i>> {
        if self.take(byte) {
            Ok(())
        } else {
            Err(self.error("unexpected delimiter"))
        }
    }

    #[inline(always)]
    fn peek_literal(&self, literal: &[u8]) -> bool {
        self.bytes.get(self.cursor..self.cursor + literal.len()) == Some(literal)
    }

    #[inline(always)]
    fn consume_literal(&mut self, literal: &'static [u8]) -> Result<(), DirectBuildError<'i>> {
        if self.peek_literal(literal) {
            self.cursor += literal.len();
            Ok(())
        } else {
            Err(self.error("invalid literal"))
        }
    }

    #[inline(always)]
    fn parse_string(&mut self) -> Result<Cow<'i, str>, DirectBuildError<'i>> {
        if self.bytes.get(self.cursor) != Some(&b'"') {
            return Err(self.error("expected string"));
        }
        if let Some(raw_end) = self.tiny_plain_string_end() {
            let raw = unsafe {
                std::str::from_utf8_unchecked(&self.bytes[self.cursor + 1..raw_end - 1])
            };
            self.cursor = raw_end;
            return Ok(Cow::Borrowed(raw));
        }
        let span = match_string_at_quote_trusted_utf8(self.bytes, self.cursor)
            .map_err(|_| self.error("invalid string"))?;
        let raw = unsafe {
            std::str::from_utf8_unchecked(&self.bytes[span.content_start()..span.content_end()])
        };
        self.cursor = span.raw_end;
        if span.needs_decode() {
            unescape_string(raw).map_err(|_| self.error("invalid string escape"))
        } else {
            Ok(Cow::Borrowed(raw))
        }
    }

    #[allow(dead_code)]
    #[inline(always)]
    fn parse_bool(&mut self) -> Result<bool, DirectBuildError<'i>> {
        if self.peek_literal(b"true") {
            self.cursor += 4;
            Ok(true)
        } else if self.peek_literal(b"false") {
            self.cursor += 5;
            Ok(false)
        } else {
            Err(self.error("expected bool"))
        }
    }

    #[allow(dead_code)]
    #[inline(always)]
    fn skip_bool(&mut self) -> Result<(), DirectBuildError<'i>> {
        if self.peek_literal(b"true") {
            self.cursor += 4;
            Ok(())
        } else if self.peek_literal(b"false") {
            self.cursor += 5;
            Ok(())
        } else {
            Err(self.error("expected bool"))
        }
    }

    #[allow(dead_code)]
    #[inline(always)]
    fn parse_i64(&mut self) -> Result<i64, DirectBuildError<'i>> {
        let span = self.number_span()?;
        materialize_i64(self.bytes, &span).map_err(|_| self.error("integer range"))
    }

    #[inline(always)]
    fn parse_u64(&mut self) -> Result<u64, DirectBuildError<'i>> {
        let span = self.number_span()?;
        materialize_u64(self.bytes, &span).map_err(|_| self.error("integer range"))
    }

    #[allow(dead_code)]
    #[inline(always)]
    fn parse_u32(&mut self) -> Result<u32, DirectBuildError<'i>> {
        let value = self.parse_u64()?;
        u32::try_from(value).map_err(|_| self.error("integer range"))
    }

    #[allow(dead_code)]
    #[inline(always)]
    fn parse_f64(&mut self) -> Result<f64, DirectBuildError<'i>> {
        let span = self.number_span()?;
        materialize_f64(self.bytes, &span).map_err(|_| self.error("float range"))
    }

    #[inline(always)]
    fn number_span(&mut self) -> Result<parse_that_regex::number::NumberSpan, DirectBuildError<'i>> {
        let Some(first) = self.bytes.get(self.cursor).copied() else {
            return Err(self.error("expected number"));
        };
        let span = match_number_span_from_first(self.bytes, self.cursor, first)
            .ok_or_else(|| self.error("invalid number"))?;
        self.cursor = span.end;
        Ok(span)
    }

    fn skip_value(&mut self) -> Result<(), DirectBuildError<'i>> {
        self.ws();
        let Some(byte) = self.bytes.get(self.cursor).copied() else {
            return Err(self.error("expected value"));
        };
        match byte {
            b'{' => self.skip_object(),
            b'[' => self.skip_array(),
            b'"' => self.skip_string_raw(),
            b'-' | b'0'..=b'9' => self.number_span().map(|_| ()),
            b't' => self.consume_literal(b"true"),
            b'f' => self.consume_literal(b"false"),
            b'n' => self.consume_literal(b"null"),
            _ => Err(self.error("expected value")),
        }
    }

    fn skip_object(&mut self) -> Result<(), DirectBuildError<'i>> {
        self.expect(b'{')?;
        self.ws();
        if self.take(b'}') {
            return Ok(());
        }
        loop {
            self.skip_string_raw()?;
            self.ws();
            self.expect(b':')?;
            self.skip_value()?;
            self.ws();
            if self.take(b',') {
                self.ws();
                continue;
            }
            self.expect(b'}')?;
            return Ok(());
        }
    }

    fn skip_array(&mut self) -> Result<(), DirectBuildError<'i>> {
        self.expect(b'[')?;
        self.ws();
        if self.take(b']') {
            return Ok(());
        }
        loop {
            self.skip_value()?;
            self.ws();
            if self.take(b',') {
                self.ws();
                continue;
            }
            self.expect(b']')?;
            return Ok(());
        }
    }

    #[inline(always)]
    fn skip_string_raw(&mut self) -> Result<(), DirectBuildError<'i>> {
        if self.bytes.get(self.cursor) != Some(&b'"') {
            return Err(self.error("expected string"));
        }
        if let Some(raw_end) = self.skip_plain_string_end() {
            self.cursor = raw_end;
            return Ok(());
        }
        let span = match_string_at_quote_trusted_utf8(self.bytes, self.cursor)
            .map_err(|_| self.error("invalid string"))?;
        self.cursor = span.raw_end;
        Ok(())
    }

    #[inline(always)]
    fn tiny_plain_string_end(&self) -> Option<usize> {
        let mut cursor = self.cursor + 1;
        let limit = (cursor + 32).min(self.bytes.len());
        while cursor < limit {
            match self.bytes[cursor] {
                b'"' => return Some(cursor + 1),
                b'\\' | 0x00..=0x1f => return None,
                _ => cursor += 1,
            }
        }
        None
    }

    #[inline(always)]
    fn skip_plain_string_end(&self) -> Option<usize> {
        let mut cursor = self.cursor + 1;
        let limit = (cursor + 96).min(self.bytes.len());
        while cursor < limit {
            match self.bytes[cursor] {
                b'"' => return Some(cursor + 1),
                b'\\' | 0x00..=0x1f => return None,
                _ => cursor += 1,
            }
        }
        None
    }

    #[inline(always)]
    fn error(&self, message: &'static str) -> DirectBuildError<'i> {
        DirectBuildError {
            input: self.input,
            offset: self.cursor,
            message,
        }
    }
}
